From b80a483d324262d1f91bac99027b6133f91c1c22 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:50:15 +0100
Subject: [PATCH] shell: make Esc in Panel Settings do what its button does

Esc only hid Panel Settings, while its button also leaves edit mode when
it was entered just for the panel. Make Esc trigger the same action, and
reset the flag picking the button when leaving edit mode from the menu.

BUG: 522199
---
 shell/desktopview.cpp     | 3 ++-
 shell/panelconfigview.cpp | 6 +++++-
 2 files changed, 7 insertions(+), 2 deletions(-)

diff --git a/shell/desktopview.cpp b/shell/desktopview.cpp
index 09ed56a17e..f86bcf3261 100644
--- a/shell/desktopview.cpp
+++ b/shell/desktopview.cpp
@@ -523,10 +523,11 @@ void DesktopView::slotContainmentChanged()
         auto *desktopEditMode = new QAction(QIcon::fromTheme(QStringLiteral("document-edit")), i18n("Enter Edit Mode"), m_containment);
         QAction *editMode = m_containment->corona()->action(QStringLiteral("edit mode"));
         m_containment->setInternalAction(QStringLiteral("desktop edit mode"), desktopEditMode);
-        connect(desktopEditMode, &QAction::triggered, editMode, &QAction::triggered);
+        // Set before toggling edit mode, so that leaving edit mode from here resets it
         connect(desktopEditMode, &QAction::triggered, [&]() {
             m_enteredEditMode = true;
         });
+        connect(desktopEditMode, &QAction::triggered, editMode, &QAction::triggered);
         connect(m_containment->corona(), &Plasma::Corona::editModeChanged, this, [this](bool editMode) {
             if (!editMode) {
                 m_enteredEditMode = false;
diff --git a/shell/panelconfigview.cpp b/shell/panelconfigview.cpp
index 7af58da0c3..d15fa610a9 100644
--- a/shell/panelconfigview.cpp
+++ b/shell/panelconfigview.cpp
@@ -317,7 +317,11 @@ void PanelConfigView::keyPressEvent(QKeyEvent *ev)

     if (ev->matches(QKeySequence::Cancel)) {
         ev->accept();
-        hide();
+        if (QAction *configureAction = m_containment->internalAction(u"configure"_s); configureAction && configureAction->isEnabled()) {
+            configureAction->trigger();
+        } else {
+            hide();
+        }
     }
 }

